-- Step 1: remove the three demo cafés (their menus go with them).
delete from places where slug in ('olive-cafe','circle-cafe','siblings');

-- Step 2: add The Chicken Box with 20 categories and 111 items.
with p as (insert into places(name,name_ne,slug,type,logo_url,cover_url,description,is_active,sort_order) values('The Chicken Box','द चिकेन बक्स','the-chicken-box','food','/images/places/the-chicken-box-logo.webp','/images/places/the-chicken-box-cover.webp','Finger Lickin'' Chicken. Fried chicken, burgers, wraps, pizza, tacos and combos.',true,1) returning id)
, c as (insert into categories(place_id,name,sort_order) select p.id,v.n,v.s from p, (values ('TCB Combos',1),('Hot & Crispy Leg Piece',2),('Hot & Crispy Chest',3),('Crispy Hot Wings',4),('Crispy Boneless Strips',5),('Crispy Chicken Popcorn',6),('Chicken Nuggets',7),('Smoky Grilled Chicken',8),('Burger',9),('Veg Burger',10),('Sandwich',11),('Mexican Wrap',12),('Pizza',13),('Mexican Tacos',14),('Cutlet',15),('Chicken Sausage Masala',16),('French Fries',17),('Dips',18),('Refreshing Drinks',19),('Mocktails',20)) v(n,s) returning id,name)
